1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import { connectionTarget, serverRootPassword } from "../lib/sftp";
4	import {
5	  familyFor,
6	  schemaFor,
7	  validateConfig,
8	  GAME_CONFIG_VERSION,
9	} from "../lib/game-config";
10	import { Client, type ClientChannel, type SFTPWrapper } from "ssh2";
11	import type { Job } from "@prisma/client";
12	
13	/**
14	 * GAME_CONFIG handler — apply a game server's customization (variant + settings).
15	 *
16	 * `worker/index.ts` owns the job loop and its `handlers` map; wire this in there:
17	 *   GAME_CONFIG: gameConfigApply,
18	 *
19	 * Ownership + validation happen at enqueue time (lib/actions-game-config.ts), so
20	 * this handler trusts `Server.gameVariant` / `Server.gameConfig`.
21	 *
22	 * TWO PATHS:
23	 *  - DEFAULT (simulation): records an "applied" marker on `Server.gameConfig` and
24	 *    notifies the user. No SSH, no VM mutation. This runs under SANDBOX and, in
25	 *    production, whenever the real path is NOT explicitly enabled. It keeps the
26	 *    portal flow (save → job → "applied" notification) working end to end.
27	 *
28	 *  - REAL (gated): actually pushes the settings to the live game server over SSH.
29	 *    Runs ONLY when `!SANDBOX && process.env.ENABLE_REAL_GAMECFG === "1"`. It is
30	 *    deliberately non-destructive (read-modify-write for key=value files; never
31	 *    clobbers a config it can't find/parse) and fully wrapped in try/catch so a
32	 *    failure notifies the user but never crashes the worker.
33	 *
34	 * Enable the real path only once the per-family config paths / service names below
35	 * have been confirmed for the actual game-server images.
36	 */
37	
38	/** True only when the operator has explicitly opted into real (non-sandbox) apply. */
39	const REAL_APPLY_ENABLED = !SANDBOX && process.env.ENABLE_REAL_GAMECFG === "1";
40	
41	const CONNECT_TIMEOUT_MS = 15_000;
42	const EXEC_TIMEOUT_MS = 30_000;
43	
44	async function notify(userId: string, title: string, body?: string, href?: string) {
45	  try {
46	    await db.notification.create({ data: { userId, title, body, href } });
47	  } catch (e) {
48	    console.error("[game-config] notify failed", e);
49	  }
50	}
51	
52	export async function gameConfigApply(job: Job): Promise<void> {
53	  const serverId = job.serverId;
54	  if (!serverId) throw new Error("game config: job has no serverId");
55	
56	  const server = await db.server.findUnique({
57	    where: { id: serverId },
58	    include: { osTemplate: true, gamePlan: true, dedicatedIp: true },
59	  });
60	  if (!server) throw new Error(`Server ${serverId} not found`);
61	
62	  const family = familyFor(server);
63	  const schema = schemaFor(family);
64	  if (!family || !schema) {
65	    throw new Error(`game config: ${server.hostname} is not a customizable game server`);
66	  }
67	
68	  const variant = server.gameVariant ?? schema.defaultVariant;
69	
70	  // -------------------------------------------------------------------------
71	  // DEFAULT PATH — simulation (unchanged). Runs under SANDBOX and whenever the
72	  // real path is not explicitly enabled. We stamp a small applied-marker
73	  // alongside the existing values so the portal can show the last-applied
74	  // variant/time, then notify the user. No SSH, no VM mutation.
75	  // -------------------------------------------------------------------------
76	  if (!REAL_APPLY_ENABLED) {
77	    const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
78	    const marker = {
79	      _appliedVariant: variant,
80	      _appliedAt: new Date().toISOString(),
81	      _configVersion: GAME_CONFIG_VERSION,
82	      _sandbox: SANDBOX,
83	    };
84	
85	    await db.server.update({
86	      where: { id: server.id },
87	      data: { gameConfig: { ...existing, ...marker } as any },
88	    });
89	
90	    await notify(
91	      server.userId,
92	      `Game settings applied on ${server.hostname}`,
93	      `${schema.label} (${variant}) settings were applied${SANDBOX ? " (sandbox)" : ""}.`,
94	      `/dashboard/servers/${server.id}?tab=game settings`
95	    );
96	    return;
97	  }
98	
99	  // -------------------------------------------------------------------------
100	  // REAL PATH — gated behind ENABLE_REAL_GAMECFG. Everything below is wrapped so
101	  // a failure notifies the user but never throws out of the handler.
102	  // -------------------------------------------------------------------------
103	  const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
104	  const valid = validateConfig(family, existing);
105	  // `existing` also holds the `_`-prefixed markers; validateConfig drops unknown
106	  // keys, so `values` is exactly the schema fields keyed on the game's own keys.
107	  const values = valid.ok ? valid.values : {};
108	
109	  let outcome: ApplyOutcome = { ok: false, applied: [], notes: [] };
110	  try {
111	    outcome = await applyRealConfig(server, family, values);
112	  } catch (e) {
113	    const msg = e instanceof Error ? e.message : String(e);
114	    console.error(`[game-config] real apply failed on ${server.hostname}:`, e);
115	    outcome = { ok: false, applied: [], notes: [`Apply failed: ${msg}`] };
116	  }
117	
118	  // Always record the applied-marker (even on partial/soft failure) so the portal
119	  // reflects the attempt, and note whether the real push succeeded.
120	  const marker = {
121	    _appliedVariant: variant,
122	    _appliedAt: new Date().toISOString(),
123	    _configVersion: GAME_CONFIG_VERSION,
124	    _sandbox: SANDBOX,
125	    _real: true,
126	    _realOk: outcome.ok,
127	  };
128	  try {
129	    await db.server.update({
130	      where: { id: server.id },
131	      data: { gameConfig: { ...existing, ...marker } as any },
132	    });
133	  } catch (e) {
134	    console.error("[game-config] marker update failed", e);
135	  }
136	
137	  const detail = [...outcome.applied, ...outcome.notes].join(" ");
138	  await notify(
139	    server.userId,
140	    outcome.ok
141	      ? `Game settings applied on ${server.hostname}`
142	      : `Game settings partially applied on ${server.hostname}`,
143	    `${schema.label} (${variant}) — ${detail || "no changes were made."}`,
144	    `/dashboard/servers/${server.id}?tab=game settings`
145	  );
146	}
147	
148	// ===========================================================================
149	// Real apply — per-family rendering + SSH transport
150	// ===========================================================================
151	
152	type Values = Record<string, string | number | boolean>;
153	type ApplyOutcome = { ok: boolean; applied: string[]; notes: string[] };
154	
155	/** The minimal Server shape the real path needs to open an SSH connection. */
156	type SshServer = {
157	  id: string;
158	  rootPassword: string | null;
159	  rootPasswordEnc?: string | null;
160	  sshPort: number | null;
161	  dedicatedIp?: { address: string } | null;
162	};
163	
164	/**
165	 * Connect to the game-server VM (host/port derived exactly like the file manager,
166	 * user "root", password `rootPassword`), run `fn`, and always close the session.
167	 */
168	function withSsh<T>(server: SshServer, fn: (conn: Client, sftp: SFTPWrapper) => Promise<T>): Promise<T> {
169	  return new Promise((resolve, reject) => {
170	    const target = connectionTarget(server as any);
171	    if (!target) {
172	      reject(new Error("server is not reachable yet — connection details are pending"));
173	      return;
174	    }
175	    const password = serverRootPassword(server);
176	    if (!password) {
177	      reject(new Error("server has no root password set"));
178	      return;
179	    }
180	
181	    const conn = new Client();
182	    let settled = false;
183	    const finish = (err: Error | null, val?: T) => {
184	      if (settled) return;
185	      settled = true;
186	      try {
187	        conn.end();
188	      } catch {
189	        /* best-effort */
190	      }
191	      if (err) reject(err);
192	      else resolve(val as T);
193	    };
194	
195	    conn.on("ready", () => {
196	      conn.sftp((err, sftp) => {
197	        if (err) return finish(err);
198	        fn(conn, sftp).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
199	      });
200	    });
201	    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
202	    conn.connect({
203	      host: target.host,
204	      port: target.port,
205	      username: "root",
206	      password,
207	      readyTimeout: CONNECT_TIMEOUT_MS,
208	    });
209	  });
210	}
211	
212	/** Read a remote text file, or null if it does not exist. */
213	function sftpRead(sftp: SFTPWrapper, path: string): Promise<string | null> {
214	  return new Promise((resolve, reject) => {
215	    sftp.readFile(path, (err, data) => {
216	      if (err) {
217	        // ENOENT / no such file → null; anything else is a real error.
218	        const code = (err as NodeJS.ErrnoException).code;
219	        if (code === "ENOENT" || code === "No such file" || /no such file/i.test(err.message)) {
220	          return resolve(null);
221	        }
222	        return reject(err);
223	      }
224	      resolve(data.toString("utf8"));
225	    });
226	  });
227	}
228	
229	/** Write a remote text file (overwrites). */
230	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
231	  return new Promise((resolve, reject) => {
232	    sftp.writeFile(path, Buffer.from(content, "utf8"), (err) => (err ? reject(err) : resolve()));
233	  });
234	}
235	
236	/** Run a remote shell command; resolves with stdout/stderr/exit-code (never rejects on non-zero). */
237	function execRemote(conn: Client, cmd: string): Promise<{ code: number; stdout: string; stderr: string }> {
238	  return new Promise((resolve, reject) => {
239	    conn.exec(cmd, (err, stream: ClientChannel) => {
240	      if (err) return reject(err);
241	      let stdout = "";
242	      let stderr = "";
243	      const timer = setTimeout(() => {
244	        try {
245	          stream.close();
246	        } catch {
247	          /* ignore */
248	        }
249	      }, EXEC_TIMEOUT_MS);
250	      stream
251	        .on("close", (code: number) => {
252	          clearTimeout(timer);
253	          resolve({ code: code ?? 0, stdout, stderr });
254	        })
255	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
256	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
257	    });
258	  });
259	}
260	
261	/**
262	 * Locate the first existing path: try explicit candidates via `test -f`, then a
263	 * bounded `find` over `findRoots` for `findName`. Returns the path or null.
264	 * Non-destructive — only reads.
265	 */
266	async function remoteLocate(
267	  conn: Client,
268	  candidates: string[],
269	  findRoots: string[],
270	  findName: string
271	): Promise<string | null> {
272	  const testExpr = candidates.map((p) => `if [ -f '${shq(p)}' ]; then echo '${shq(p)}'; exit 0; fi;`).join(" ");
273	  const findExpr = findRoots.length
274	    ? `for r in ${findRoots.map((r) => `'${shq(r)}'`).join(" ")}; do [ -d "$r" ] && find "$r" -maxdepth 6 -type f -name '${shq(findName)}' 2>/dev/null | head -1; done | head -1`
275	    : "true";
276	  const { stdout } = await execRemote(conn, `${testExpr} ${findExpr}`);
277	  const hit = stdout.split(/\r?\n/).map((s) => s.trim()).find((s) => s.length > 0);
278	  return hit ?? null;
279	}
280	
281	/** Escape a value for single-quoted shell use. */
282	function shq(s: string): string {
283	  return s.replace(/'/g, "'\\''");
284	}
285	
286	/** Dispatch to the correct family renderer. */
287	async function applyRealConfig(server: SshServer, family: string, values: Values): Promise<ApplyOutcome> {
288	  return withSsh(server, async (conn, sftp) => {
289	    switch (family) {
290	      case "minecraft":
291	        return applyMinecraft(conn, sftp, values);
292	      case "rust":
293	        return applyRust(conn, sftp, values);
294	      case "valheim":
295	        return applyValheim(conn, sftp, values);
296	      case "cs2":
297	        return applyCs2(conn, sftp, values);
298	      case "palworld":
299	        return applyPalworld(conn, sftp, values);
300	      default:
301	        return { ok: false, applied: [], notes: [`No real apply implemented for "${family}".`] };
302	    }
303	  });
304	}
305	
306	// ---------------------------------------------------------------------------
307	// key=value file helpers (server.properties)
