310	/** Update `key=value` lines in place, preserving comments/unknown lines; append missing keys. */
311	function updateKeyValue(content: string, updates: Record<string, string>): string {
312	  const lines = content.split(/\r?\n/);
313	  const seen = new Set<string>();
314	  for (let i = 0; i < lines.length; i++) {
315	    const trimmed = lines[i].trim();
316	    if (!trimmed || trimmed.startsWith("#") || trimmed.startsWith("!")) continue;
317	    const eq = lines[i].indexOf("=");
318	    if (eq < 0) continue;
319	    const key = lines[i].slice(0, eq).trim();
320	    if (Object.prototype.hasOwnProperty.call(updates, key)) {
321	      lines[i] = `${key}=${updates[key]}`;
322	      seen.add(key);
323	    }
324	  }
325	  for (const k of Object.keys(updates)) {
326	    if (!seen.has(k)) lines.push(`${k}=${updates[k]}`);
327	  }
328	  return lines.join("\n");
329	}
