331	/** Read a `key=value` file into a map (comments/blank lines ignored). */
332	function parseKeyValue(content: string): Record<string, string> {
333	  const out: Record<string, string> = {};
334	  for (const line of content.split(/\r?\n/)) {
335	    const t = line.trim();
336	    if (!t || t.startsWith("#") || t.startsWith("!")) continue;
337	    const eq = line.indexOf("=");
338	    if (eq < 0) continue;
339	    out[line.slice(0, eq).trim()] = line.slice(eq + 1).trim();
340	  }
341	  return out;
342	}
