348	/** Update `key value` (whitespace-separated) lines in place; append missing keys. */
349	function updateConvars(content: string, updates: Record<string, string>): string {
350	  const lines = content.split(/\r?\n/);
351	  const seen = new Set<string>();
352	  for (let i = 0; i < lines.length; i++) {
353	    const t = lines[i].trim();
354	    if (!t || t.startsWith("//") || t.startsWith("#")) continue;
355	    const sp = t.search(/\s/);
356	    const key = sp < 0 ? t : t.slice(0, sp);
357	    if (Object.prototype.hasOwnProperty.call(updates, key)) {
358	      lines[i] = `${key} ${updates[key]}`;
359	      seen.add(key);
360	    }
361	  }
362	  for (const k of Object.keys(updates)) {
363	    if (!seen.has(k)) lines.push(`${k} ${updates[k]}`);
364	  }
365	  return lines.join("\n");
366	}
