424	/**
425	 * Best-effort Minecraft RCON push. Reads rcon config from the (updated)
426	 * server.properties; if RCON is enabled, a password is set, and `mcrcon` exists
427	 * on the box, pushes the live-editable settings. Anything missing → note a restart.
428	 */
429	async function tryMinecraftRcon(conn: Client, props: string, v: Values, notes: string[]): Promise<void> {
430	  const kv = parseKeyValue(props);
431	  const enabled = kv["enable-rcon"] === "true";
432	  const password = kv["rcon.password"] ?? "";
433	  const port = kv["rcon.port"] || "25575";
434	  if (!enabled || !password) {
435	    notes.push("RCON is not enabled — restart the server to apply the new settings live.");
436	    return;
437	  }
438	  const which = await execRemote(conn, "command -v mcrcon || true");
439	  if (!which.stdout.trim()) {
440	    notes.push("RCON is enabled but `mcrcon` is not installed — restart to apply live.");
441	    return;
442	  }
443	
444	  // A conservative set of safe live commands. TODO(rcon): expand once the exact
445	  // runtime command set is verified for the target Minecraft build.
446	  const cmds: string[] = [];
447	  if (v["difficulty"] != null) cmds.push(`difficulty ${String(v["difficulty"])}`);
448	  if (v["white-list"] != null) cmds.push(`whitelist ${bool(v["white-list"]) === "true" ? "on" : "off"}`);
449	  if (v["pvp"] != null || v["max-players"] != null || v["motd"] != null) cmds.push("reload");
450	  if (cmds.length === 0) return;
451	
452	  const quoted = cmds.map((c) => `'${shq(c)}'`).join(" ");
453	  const res = await execRemote(
454	    conn,
455	    `mcrcon -H 127.0.0.1 -P ${shq(port)} -p '${shq(password)}' ${quoted} 2>&1 || true`
456	  );
457	  notes.push(res.code === 0 ? "Pushed live settings via RCON." : "RCON push attempted (some settings may need a restart).");
458	}
