613	/** Split a comma-separated OptionSettings body at top level (respecting quotes). */
614	function splitTopLevel(s: string): string[] {
615	  const out: string[] = [];
616	  let cur = "";
617	  let inQuote = false;
618	  for (const ch of s) {
619	    if (ch === '"') inQuote = !inQuote;
620	    if (ch === "," && !inQuote) {
621	      out.push(cur);
622	      cur = "";
623	    } else {
624	      cur += ch;
625	    }
626	  }
627	  if (cur.length) out.push(cur);
628	  return out;
629	}
