631	/**
632	 * Update keys inside the `OptionSettings=(...)` block, preserving the section
633	 * header, all other keys, and quoting. Returns null if the block can't be parsed
634	 * (so the caller soft-fails instead of clobbering the file).
635	 */
636	function updatePalworld(content: string, updates: Record<string, string>): string | null {
637	  const idx = content.indexOf("OptionSettings=(");
638	  if (idx < 0) return null;
639	  const open = content.indexOf("(", idx);
640	  const close = content.indexOf(")", open);
641	  if (open < 0 || close < 0) return null;
642	
643	  const inner = content.slice(open + 1, close);
644	  const pairs = splitTopLevel(inner);
645	  const order: string[] = [];
646	  const map = new Map<string, string>();
647	  for (const p of pairs) {
648	    const eq = p.indexOf("=");
649	    if (eq < 0) continue;
650	    const k = p.slice(0, eq).trim();
651	    order.push(k);
652	    map.set(k, p.slice(eq + 1));
653	  }
654	  for (const [k, val] of Object.entries(updates)) {
655	    if (!map.has(k)) order.push(k);
656	    map.set(k, val);
657	  }
658	  const rebuilt = order.map((k) => `${k}=${map.get(k)}`).join(",");
659	  return content.slice(0, open + 1) + rebuilt + content.slice(close);
660	}
