41	/**
42	 * Build a best-effort remote update command. For steamcmd-based games we run an
43	 * anonymous `app_update ... validate` if steamcmd is present, then (always)
44	 * restart the matching systemd service. Everything is tolerant (`|| true`) so a
45	 * missing tool/service never fails the whole job for an otherwise-healthy VM.
46	 */
47	function updateCommand(family: GameFamily): string {
48	  const appId = STEAM_APPID[family];
49	  const svc = SERVICE_HINT[family];
50	  const steam = appId
51	    ? `if command -v steamcmd >/dev/null 2>&1; then steamcmd +login anonymous +app_update ${appId} validate +quit || true; fi; `
52	    : "";
53	  // Restart the named service, then a "<family>-server" variant, then any unit
54	  // whose name contains the family; never hard-fail.
55	  const restart =
56	    `systemctl restart ${svc} 2>/dev/null || ` +
57	    `systemctl restart ${svc}-server 2>/dev/null || ` +
58	    `svc=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${family} | head -1 | awk '{print $1}'); ` +
59	    `if [ -n "$svc" ]; then systemctl restart "$svc" || true; fi`;
60	  return `set -e; ${steam}${restart}; true`;
61	}
