63	async function loadGameServer(serverId: string) {
64	  const server = await db.server.findUnique({
65	    where: { id: serverId },
66	    include: { osTemplate: true },
67	  });
68	  if (!server) throw new Error(`Server ${serverId} not found`);
69	  return server;
70	}
